#include <bits/stdc++.h>
using namespace std;

const int INF = 0x3f3f3f3f;
const int MAXN = 410;
const int MAXM = 200020;
const int dir[4][2] = {{-1, 0}, {0, 1}, {1, 0}, {0, -1}};

int firstEdge[MAXN], vertex[MAXM], nextEdge[MAXM], capacity[MAXM], usedFlow[MAXM], edgeCnt;
int height[MAXN], current[MAXN], sourceNode, sinkNode;

struct SimpleQueue {
    int a[100000];
    int head, tail;
    void clear() { head = tail = 0; }
    void push(int x) { a[tail++] = x; }
    void pop() { ++head; }
    int front() const { return a[head]; }
    bool empty() const { return head == tail; }
};

void initGraph() {
    memset(firstEdge, -1, sizeof(firstEdge));
    edgeCnt = 0;
}

void addEdge(int u, int v, int c) {
    vertex[edgeCnt] = v;
    nextEdge[edgeCnt] = firstEdge[u];
    capacity[edgeCnt] = c;
    usedFlow[edgeCnt] = 0;
    firstEdge[u] = edgeCnt++;

    vertex[edgeCnt] = u;
    nextEdge[edgeCnt] = firstEdge[v];
    capacity[edgeCnt] = 0;
    usedFlow[edgeCnt] = 0;
    firstEdge[v] = edgeCnt++;
}

bool buildLevels() {
    memset(height, -1, sizeof(height));
    SimpleQueue q;
    q.clear();
    height[sourceNode] = 0;
    q.push(sourceNode);
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int e = firstEdge[u]; e != -1; e = nextEdge[e]) {
            int v = vertex[e];
            if (height[v] == -1 && capacity[e] > usedFlow[e]) {
                height[v] = height[u] + 1;
                q.push(v);
            }
        }
    }
    return height[sinkNode] != -1;
}

int augment(int u, int pushed) {
    if (u == sinkNode || pushed == 0) return pushed;
    int sent = 0;
    for (int &e = current[u]; e != -1; e = nextEdge[e]) {
        int v = vertex[e];
        if (height[v] == height[u] + 1 && capacity[e] > usedFlow[e]) {
            int tmp = augment(v, min(pushed, capacity[e] - usedFlow[e]));
            if (tmp > 0) {
                usedFlow[e] += tmp;
                usedFlow[e ^ 1] -= tmp;
                pushed -= tmp;
                sent += tmp;
                if (pushed == 0) break;
            }
        }
    }
    return sent;
}

int maxflow(int s, int t) {
    sourceNode = s;
    sinkNode = t;
    int ans = 0;
    while (buildLevels()) {
        memcpy(current, firstEdge, sizeof(firstEdge));
        ans += augment(sourceNode, INF);
    }
    return ans;
}

int tim[12][12], dist[12][12];
char g[MAXN][MAXN], h[MAXN][MAXN];
int n, limitTime;

bool inside(int x, int y) {
    return x >= 0 && x < n && y >= 0 && y < n;
}

void bfs1(int sx, int sy) {
    memset(tim, 0x3f, sizeof(tim));
    SimpleQueue q;
    q.clear();
    q.push(sx * 10 + sy);
    tim[sx][sy] = 0;
    while (!q.empty()) {
        int x = q.front() / 10, y = q.front() % 10;
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + dir[k][0], ny = y + dir[k][1];
            if (inside(nx, ny) && g[nx][ny] >= '0' && g[nx][ny] <= '9' && tim[nx][ny] > tim[x][y] + 1) {
                tim[nx][ny] = tim[x][y] + 1;
                q.push(nx * 10 + ny);
            }
        }
    }
}

void bfs2(int sx, int sy) {
    memset(dist, 0x3f, sizeof(dist));
    SimpleQueue q;
    q.clear();
    q.push(sx * 10 + sy);
    dist[sx][sy] = 0;
    while (!q.empty()) {
        int x = q.front() / 10, y = q.front() % 10;
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + dir[k][0], ny = y + dir[k][1];
            if (inside(nx, ny) && h[nx][ny] >= '0' && h[nx][ny] <= '9' && dist[nx][ny] > dist[x][y] + 1) {
                if (tim[nx][ny] >= dist[x][y] + 1) {
                    dist[nx][ny] = dist[x][y] + 1;
                    if (tim[nx][ny] > dist[nx][ny])
                        q.push(nx * 10 + ny);
                }
            }
        }
    }
}

int main() {
    scanf("%d%d", &n, &limitTime);
    for (int i = 0; i < n; ++i) scanf("%s", g[i]);
    for (int i = 0; i < n; ++i) scanf("%s", h[i]);

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (g[i][j] == 'Z')
                bfs1(i, j);

    int S = 0, T = n * n * 2 + 1;
    initGraph();

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            if (g[i][j] > '0' && g[i][j] <= '9')
                addEdge(S, i * n + j + 1, g[i][j] - '0');
            if (h[i][j] > '0' && h[i][j] <= '9')
                addEdge(n * n + i * n + j + 1, T, h[i][j] - '0');
        }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (g[i][j] > '0' && g[i][j] <= '9') {
                bfs2(i, j);
                for (int x = 0; x < n; ++x)
                    for (int y = 0; y < n; ++y)
                        if (h[x][y] > '0' && h[x][y] <= '9' && dist[x][y] <= limitTime)
                            addEdge(i * n + j + 1, n * n + x * n + y + 1, INF);
            }

    printf("%d\n", maxflow(S, T));
    return 0;
}
